import React, { useState, useEffect } from 'react';
import './HomePage.css';
import Header from './Header';
import HeroSection from './HeroSection';
import FeaturedMovies from './FeaturedMovies';
import MovieCategories from './MovieCategories';
import PopularMovies from './PopularMovies';
import Footer from './Footer';
import defaultDatabase from '../../data/database';

function HomePage({ currentUser, onNavigate, onGoToAuth, onGoToTickets, onGoToAdmin, onLogout, scrollTarget, onClearScrollTarget }) {
  const [movies, setMovies] = useState([]);
  const [filteredMovies, setFilteredMovies] = useState([]);
  const [selectedGenre, setSelectedGenre] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    setMovies(defaultDatabase.movies || []);
    setFilteredMovies(defaultDatabase.movies || []);
  }, []);

  useEffect(() => {
    if (!scrollTarget) return;
    const targetElement = document.getElementById(scrollTarget);
    if (targetElement) {
      targetElement.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
    onClearScrollTarget();
  }, [scrollTarget, onClearScrollTarget]);

  // Lọc phim theo thể loại
  useEffect(() => {
    let filtered = movies;

    if (selectedGenre !== 'All') {
      filtered = filtered.filter(movie => {
        if (!movie.genre) return false;
        if (Array.isArray(movie.genre)) {
          return movie.genre.includes(selectedGenre);
        }
        return movie.genre === selectedGenre;
      });
    }

    if (searchTerm.trim()) {
      filtered = filtered.filter(movie =>
        movie.title.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    setFilteredMovies(filtered);
  }, [selectedGenre, searchTerm, movies]);

  const handleSelectMovie = (movie) => {
    onNavigate('showtime-list', movie);
  };

  const getAllGenres = () => {
    const genresSet = new Set(['All']);
    movies.forEach(movie => {
      if (movie.genre && Array.isArray(movie.genre)) {
        movie.genre.forEach(g => genresSet.add(g));
      }
    });
    return Array.from(genresSet);
  };

  return (
    <div className="home-page" id="home">
      <Header 
        currentUser={currentUser} 
        onGoToAuth={onGoToAuth}
        onGoToTickets={onGoToTickets}
        onGoToAdmin={onGoToAdmin}
        onLogout={onLogout}
        onNavigate={onNavigate}
      />
      
      <HeroSection 
        onNavigate={onNavigate}
      />

      <div className="homepage-content">
        {/* Search Section */}
        <section className="search-section" id="movies">
          <div className="search-container">
            <input
              type="text"
              placeholder="🔍 Tìm kiếm phim yêu thích của bạn..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="search-input"
            />
          </div>
        </section>

        {/* Featured Movies */}
        <section id="deals">
          <FeaturedMovies 
            movies={movies.slice(0, 4)} 
            onSelectMovie={handleSelectMovie}
          />
        </section>

        {/* Movie Categories */}
        <section id="genres">
          <MovieCategories 
            genres={getAllGenres()}
            selectedGenre={selectedGenre}
            onSelectGenre={setSelectedGenre}
          />
        </section>

        {/* Popular Movies */}
        <section id="new">
          <PopularMovies 
            movies={filteredMovies}
            onSelectMovie={handleSelectMovie}
          />
        </section>
      </div>

      <Footer />
    </div>
  );
}

export default HomePage;
